// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceHostEmbedder {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceHostEmbedder = UniffiVTableCallbackInterfaceHostEmbedder(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeHostEmbedder.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface HostEmbedder: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeHostEmbedder.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface HostEmbedder: handle missing in uniffiClone")
            }
        },
        dims: { (
            uniffiHandle: UInt64,
            uniffiOutReturn: UnsafeMutablePointer<UInt32>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in

            let makeCall: @Sendable () throws -> UInt32 = {
                () throws -> UInt32 in
                guard let uniffiObj = try? FfiConverterTypeHostEmbedder.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.dims(
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterUInt32.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        embed: { (
            uniffiHandle: UInt64,
            texts: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            nonisolated(unsafe) let texts = texts

            let makeCall: @Sendable () throws -> [[Float]] = {
                () throws -> [[Float]] in
                guard let uniffiObj = try? FfiConverterTypeHostEmbedder.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.embed(
                     texts: try FfiConverterSequenceString.lift(texts)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterSequenceSequenceFloat.lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeHostError_lower
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceHostEmbedder> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceHostEmbedder>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
